INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-286-incorrect','quiz-neuro-ap1-286','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-287',unit_id,'quiz-topic-neuro-ap1','Que ponto corresponde à confluência lambdóide-parietomastoideia-occipitomastoideia?',NULL,'O <strong>astérion</strong> é a junção das suturas lambdóide, parietomastoideia e occipitomastoideia. Profundamente, relaciona-se com a transição entre os seios transverso e sigmóide, embora a relação exata seja variável.<p><small>Gray’s Anatomy, 42.ª ed., cap. 34, p. 561; secção de anatomia de superfície.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-287-answer','quiz-neuro-ap1-287','Astérion',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-287-incorrect','quiz-neuro-ap1-287','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-288',unit_id,'quiz-topic-neuro-ap1','Que ponto corresponde à maior proeminência do ângulo mandibular?',NULL,'Na terminologia craniométrica utilizada na AP1, o <strong>gonion</strong> corresponde ao ponto mais proeminente do ângulo da mandíbula. A 42.ª edição consultada descreve o ângulo mandibular e o ângulo goníaco, mas não foi localizada uma definição nominal explícita deste ponto, pelo que esta formulação não é atribuída a essa obra.<p><small>Conteúdo da AP1; definição nominal não localizada explicitamente no Gray’s Anatomy, 42.ª ed. consultado.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-288-answer','quiz-neuro-ap1-288','Gonion',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-288-incorrect','quiz-neuro-ap1-288','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-289',unit_id,'quiz-topic-neuro-ap1','Que ponto craniométrico se relaciona com a artéria meníngea média?',NULL,'O <strong>ptérion</strong> é a junção, aproximadamente em H, do frontal, parietal, asa maior do esfenóide e parte escamosa do temporal. Relaciona-se frequentemente em profundidade com o ramo anterior da artéria meníngea média e também com a fissura lateral do hemisfério cerebral.<p><small>Gray’s Anatomy, 42.ª ed., p. 561.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-289-answer','quiz-neuro-ap1-289','Ptérion',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-289-incorrect','quiz-neuro-ap1-289','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-290',unit_id,'quiz-topic-neuro-ap1','Em que sexo são geralmente mais pronunciados os arcos supraciliares?',NULL,'O crânio <strong>masculino</strong> apresenta ainda, em média, bordos orbitários mais espessos e arredondados, arcos supraorbitários pronunciados, glabela bem definida, linhas temporais mais marcadas e uma crista supramastoideia que se prolonga posteriormente ao meato acústico externo. Outros locais de inserção muscular refletem igualmente a necessidade biomecânica de sustentar uma cabeça masculina mais robusta.<p><small>Gray’s Anatomy, 42.ª ed., p. 571.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-290-answer','quiz-neuro-ap1-290','Masculino',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-290-incorrect','quiz-neuro-ap1-290','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-291',unit_id,'quiz-topic-neuro-ap1','Como é geralmente a fronte feminina?',NULL,'Em termos gerais, o crânio masculino é mais robusto do que o crânio feminino, mais gracil, embora existam importantes variações genéticas e populacionais. A fronte feminina é geralmente mais <strong>alta, vertical e arredondada</strong>. A mandíbula masculina tende a ser maior e mais robusta, com maior altura na região da sínfise mentoniana, mento mais quadrangular, côndilos maiores, locais de inserção muscular mais marcados e ângulo goníaco frequentemente inferior a 125°.<p><small>Gray’s Anatomy, 42.ª ed., p. 571.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-291-answer','quiz-neuro-ap1-291','Alta, vertical e arredondada',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-291-incorrect','quiz-neuro-ap1-291','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-292',unit_id,'quiz-topic-neuro-ap1','Como é geralmente o mento masculino?',NULL,'A fronte feminina é geralmente mais alta, vertical e arredondada. A mandíbula masculina tende a ser maior e mais robusta, com maior altura na região da sínfise mentoniana, mento <strong>mais quadrangular</strong>, côndilos maiores, locais de inserção muscular mais marcados e ângulo goníaco frequentemente inferior a 125°. O crânio masculino apresenta ainda, em média, bordos orbitários mais espessos e arredondados, arcos supraorbitários pronunciados, glabela bem definida, linhas temporais mais marcadas e uma crista supramastoideia que se prolonga posteriormente ao meato acústico externo.<p><small>Gray’s Anatomy, 42.ª ed., p. 571.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-292-answer','quiz-neuro-ap1-292','Mais quadrangular',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-292-incorrect','quiz-neuro-ap1-292','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-293',unit_id,'quiz-topic-neuro-ap1','Como é geralmente a apófise mastoideia masculina?',NULL,'Entre os acidentes ósseos associados às inserções musculares, <strong>a apófise mastoideia é geralmente mais robusta no sexo masculino</strong>; a descrição do temporal assinala também que tende a ser maior no homem adulto.<p><small>Gray’s Anatomy, 42.ª ed., p. 571; cap. 42, p. 737.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
