INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-293-incorrect','quiz-neuro-ap1-293','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-294',unit_id,'quiz-topic-neuro-ap1','Que ângulo goníaco é frequente no crânio masculino?',NULL,'A fronte feminina é geralmente mais alta, vertical e arredondada. A mandíbula masculina tende a ser maior e mais robusta, com maior altura na região da sínfise mentoniana, mento mais quadrangular, côndilos maiores, locais de inserção muscular mais marcados e ângulo goníaco frequentemente <strong>inferior a 125°</strong>. O crânio masculino apresenta ainda, em média, bordos orbitários mais espessos e arredondados, arcos supraorbitários pronunciados, glabela bem definida, linhas temporais mais marcadas e uma crista supramastoideia que se prolonga posteriormente ao meato acústico externo.<p><small>Gray’s Anatomy, 42.ª ed., p. 571.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
