INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-295',unit_id,'quiz-topic-neuro-ap1','Em que fase se torna evidente o dimorfismo sexual craniano?',NULL,'É igualmente difícil atribuir sexo à face de uma criança, porque as faces de rapazes e raparigas pré-púberes são semelhantes. <strong>O dimorfismo sexual torna-se geralmente evidente apenas com o desenvolvimento sexual secundário.</strong> O crescimento facial feminino termina mais cedo do que o masculino e, por isso, as características femininas tendem a conservar um padrão mais paedomórfico.<p><small>Gray’s Anatomy, 42.ª ed., pp. 570–571.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-295-answer','quiz-neuro-ap1-295','Com desenvolvimento sexual secundário',1,1);
